const ANON_IDS = [20,21,22,23,24,25,26,104,105,106,107,108,109,110,113,154,155,156,159,160,161,162,163,164,165,166,168,171,172,173,174,195

];
LIT_DATA.forEach(d => { d.anon = ANON_IDS.includes(d.id); });



  const TODAY = new Date();
  const state = { view:"all", q:"", type:"", region:"", genre:"", status:"", anon:"", sort:"" };
  const $ = s => document.querySelector(s);
  const isEvent = d => ["征文活动", "征文大赛", "征文"].includes(d.type);
  const statusOf = d => { const deadline = /^\d{4}-\d{2}-\d{2}$/.test(d.deadline || "") ? new Date(d.deadline + "T23:59:59") : null; return !deadline || Number.isNaN(deadline.getTime()) ? "待确认" : deadline >= TODAY ? "进行中" : "已截止"; };
  const TYPE_GROUPS = { literary:["文学期刊","纯文学期刊","综合文学期刊","文学杂志","诗歌期刊","少年文学期刊","散文期刊","故事期刊","诗刊","内刊文学","报纸副刊"], press:["综合报刊","杂志","综合期刊","综合杂志","选刊","评论期刊","学术期刊","杂志栏目","科普杂志","作文指导期刊"], newspaper:["报纸评论","报纸副刊"], event:["征文活动","征文大赛","征文"], wechat:["公众号"], webnovel:["网文平台","平台","短故事平台","网络文学平台","非虚构写作平台"] };
  const viewTypes = v => v==="all" ? Object.values(TYPE_GROUPS).flat() : (TYPE_GROUPS[v]||[]);
  const inView = (d,v) => v === "all" || viewTypes(v).includes(d.type);

  // 计数
  const count = v => LIT_DATA.filter(d=>inView(d,v)).length;
  ["Literary","Press","Newspaper","Wechat","Webnovel","Event"].forEach(k=>{
    const n = count(k.charAt(0).toLowerCase()+k.slice(1));
    $("#c"+k).textContent = "(" + n + ")";
    const tab = document.querySelector('#tabs .tab[data-view="'+k.charAt(0).toLowerCase()+k.slice(1)+'"]');
    if(tab) tab.style.display = n ? "" : "none";
  });
  $("#total").textContent = LIT_DATA.length;

  // 稿费字段（核心）
  function payLine(d){
    if(d.payment) return d.payment;
    if(isEvent(d)) return d.prize || "奖金/证书（以官方公告为准）";
    if(d.type==="文学期刊"||d.type==="报纸副刊") return "稿费从优·按质量计酬（文学/副刊普遍千字200–600元，以用稿通知为准）";
    if(d.type==="报纸评论") return "采用付酬·评论稿费按质量计酬（省级大报评论稿费约500–1000元/千字，以用稿通知为准）";
    if(d.type==="网文平台") return "保底+分成+全勤机制（具体档位以平台规则为准）";
    return "采用付酬（以用稿通知为准）";
  }

  // 稿酬星级（1–5，用于排序与展示）
  function payScore(d){
    if(isEvent(d)) return statusOf(d)==="进行中" ? 4 : 3;
    if(d.type==="网文平台") return 5;
    if(d.type==="文学期刊" && !d.payment){
      if(/(花城|收获|当代|十月|人民文学|北京文学|芳草|诗刊|钟山|作家)/.test(d.name)) return 5;
      return 3;
    }
    const s = (d.payment||"") + " " + (d.name||"") + " " + (d.blurb||"");
    const m = s.match(/\d[\d,]{1,5}元/g);
    let max = 0;
    if(m){ m.forEach(x=>{ const v=parseInt(x.replace(/[,，]/g,''),10); if(v>max) max=v; }); }
    else {
      (s.match(/\d{2,6}/g)||[]).forEach(n=>{ const v=parseInt(n,10); if(v>1900 && v<2100) return; if(v>max) max=v; });
    }
    if(max>=2000) return 5;
    if(max>=800) return 4;
    if(max>=300) return 3;
    if(max>=100) return 2;
    if(max>0) return 1;
    return 2;
  }
  const STAR = "★★★★★";
  function starsHtml(d){
    const n = payScore(d);
    return '<span class="stars">' + STAR.slice(0,n) + '<span class="lv">稿酬' + n + '级</span></span>';
  }

  // 筛选组构建
  function buildFilters(){
    const f = $("#filters"); f.innerHTML = "";
    if(state.view === "event"){
      addGrp(f, "状态", [["进行中","进行中"],["已截止","已截止"],["待确认","待确认"]], "status", "evt");
      const evRegions = [...new Set(LIT_DATA.filter(isEvent).map(d=>d.region))].sort();
      addGrp(f, "地域", evRegions.map(r=>[r,r]), "region", "sec");
    } else {
      const types = state.view === "all" ? [...new Set(LIT_DATA.map(d => d.type).filter(Boolean))].sort() : viewTypes(state.view);
      addGrp(f, "类型", types.map(t=>[t,t]), "type");
      const regs = [...new Set(LIT_DATA.filter(d=>inView(d,state.view)).map(d=>d.region))].sort();
      addGrp(f, "地域", regs.map(r=>[r,r]), "region", "sec");
      const gens = [...new Set(LIT_DATA.filter(d=>inView(d,state.view)).flatMap(d=>d.genres||[]))].sort();
      if(gens.length) addGrp(f, "文体", gens.map(g=>[g,g]), "genre", "sec");
      addGrp(f, "投稿方式", [["无需实名","无需实名"]], "anon", "evt");
    }
  }
  function addGrp(host, label, pairs, key, cls){
    const lab = document.createElement("div"); lab.className="grp-label"; lab.textContent=label; host.appendChild(lab);
    const wrap = document.createElement("div"); wrap.style.width="100%";
    pairs.forEach(([txt])=>{
      const c = document.createElement("span");
      c.className = "chip" + (cls?(" "+cls):"");
      c.textContent = txt;
      c.onclick = ()=>{ state[key] = (state[key]===txt)?"":txt; render(); };
      wrap.appendChild(c);
    });
    host.appendChild(wrap);
  }

  function match(d){
    if(!inView(d, state.view)) return false;
    if(state.type && d.type!==state.type) return false;
    if(state.region && d.region!==state.region) return false;
    if(state.genre && !(d.genres||[]).includes(state.genre)) return false;
    if(state.status && isEvent(d) && statusOf(d)!==state.status) return false;
    if(state.anon && !d.anon) return false;
    if(state.q){
      const hay = (d.name+d.publisher+(d.organizer||"")+(d.theme||"")+d.region+(d.genres||[]).join("")
        +d.blurb+(d.email||"")+(d.contact||"")+(d.wechat||"")+(d.platform||"")+payLine(d)).toLowerCase();
      if(!hay.includes(state.q.toLowerCase())) return false;
    }
    return true;
  }

  function contactLine(d){
    if(isEvent(d)) return d.contact ? ("投稿邮箱：" + d.contact) : "投稿方式见官方公告";
    if(d.type==="公众号") return d.email ? ("投稿：" + d.email) : ("投稿：" + (d.wechat||"公众号后台"));
    return d.email ? ("投稿：" + d.email) : "投稿方式见官网";
  }

  function render(){
    buildFilters();
    document.querySelectorAll("#tabs .tab").forEach(t=>t.classList.toggle("on", t.dataset.view===state.view));
    document.querySelectorAll("#filters .chip").forEach(c=>{
      if(state.type===c.textContent) c.classList.add("on");
      if(state.region===c.textContent) c.classList.add("on");
      if(state.genre===c.textContent) c.classList.add("on");
      if(state.status===c.textContent) c.classList.add("on");
      if(state.anon===c.textContent) c.classList.add("on");
    });

    let list = LIT_DATA.filter(match);
    if(state.sort==="high") list.sort((a,b)=>payScore(b)-payScore(a));
    else if(state.sort==="low") list.sort((a,b)=>payScore(a)-payScore(b));
    const grid = $("#grid"); grid.innerHTML="";
    $("#empty").style.display = list.length ? "none":"block";
    $("#stats").textContent = "显示 " + list.length + " / " + LIT_DATA.length + " 条" + (state.sort?" · 已按稿酬排序":"");

    list.forEach(d=>{
      const card = document.createElement("div");
      card.className="card";
      let head = '<h3>' + d.name + (isEvent(d)?'<span class="badge '+(statusOf(d)==="进行中"?"ok":"off")+'">'+statusOf(d)+'</span>':"") + '</h3>';
      let meta = '<div class="meta">' + d.type + ' · ' + d.region + ' · ' + (d.publisher||d.organizer||d.wechat||"") + ' ' + starsHtml(d) + (d.anon?' <span class="badge ok">无需实名</span>':"") + '</div>';
      let mid;
      if(isEvent(d)){
        mid = '<div class="theme">主题：' + (d.theme||"—") + ' ｜ 截稿：' + d.deadline + '</div>';
      } else {
        mid = '<div class="contact">' + contactLine(d) + '</div>'
            + '<div class="pay">稿费：' + payLine(d) + '</div>';
      }
      let tags = (d.genres||[]).map(g=>'<span class="tag">'+g+'</span>').join("");
      let blurb = '<div class="blurb">' + d.blurb + '</div>';
      card.innerHTML = head + meta + mid + (tags?'<div>'+tags+'</div>':"") + blurb;
      card.onclick=()=>openModal(d);
      grid.appendChild(card);
    });
  }

  function openModal(d){
    const m = $("#modal");
    const siteUrl = (d.site || "").match(/https?:\/\/[^\s（）"<>]+/)?.[0] || "";
    let html = '<button class="close" onclick="closeModal()">×</button><h2>'+d.name+'</h2>'+
      '<div class="m-meta">'+d.type+' · '+d.region+' · '+(d.publisher||d.organizer||d.wechat||"")+' '+starsHtml(d)+(d.anon?' <span class="badge ok">无需实名</span>':"")+'</div>';

    if(isEvent(d)){
      html += '<div class="kv"><span>截稿日期：</span>'+d.deadline+' <span class="badge '+(statusOf(d)==="进行中"?"ok":"off")+'">'+statusOf(d)+'</span></div>';
      html += '<div class="kv"><span>征文主题：</span>'+d.theme+'</div>';
      html += '<div class="kv"><span>主办单位：</span>'+d.organizer+'</div>';
      html += '<div class="kv"><span>奖项设置：</span>'+d.prize+'</div>';
      html += '<div class="kv"><span>投稿邮箱：</span>'+d.contact+'</div>';
    } else if(d.type==="公众号"){
      html += '<div class="kv"><span>平台：</span>'+(d.platform||"微信公众号")+'</div>';
      if(d.wechat) html += '<div class="kv"><span>公众号：</span>'+d.wechat+'</div>';
      html += '<div class="kv"><span>投稿方式：</span>'+(d.email||"公众号后台投稿")+'</div>';
      html += '<div class="m-pay">稿费：'+payLine(d)+'</div>';
      if(siteUrl) html += '<div class="kv"><span>相关链接：</span><a href="'+siteUrl+'" target="_blank" rel="noopener">'+siteUrl+'</a></div>';
    } else {
      html += '<div class="kv"><span>投稿邮箱：</span>'+(d.email||"以官网为准")+'</div>';
      html += '<div class="kv"><span>投稿地址：</span>'+(d.address||"—")+(d.postcode?("（邮编 "+d.postcode+"）"):"")+'</div>';
      html += '<div class="m-pay">稿费：'+payLine(d)+'</div>';
      if(siteUrl) html += '<div class="kv"><span>官方网站：</span><a href="'+siteUrl+'" target="_blank" rel="noopener">'+siteUrl+'</a></div>';
    }
    const sourceUrl = [d.source, d.site].find(v => /^https?:\/\/[^\s（）]+$/.test(v || ''));
    if(sourceUrl) html += '<div class="kv"><span>参考来源：</span><a href="'+sourceUrl+'" target="_blank" rel="noopener noreferrer">查看来源</a>（请核实最新信息）</div>';
    html += '<div class="row"><b>征稿要点</b><div class="m-blurb">'+d.blurb+'</div></div>';
    html += '<div class="row"><b>投稿要求</b><div class="m-req">'+d.requirement+'</div></div>';
    html += '<div class="row"><b>征稿文体</b>：'+(d.genres||[]).map(g=>'<span class="tag">'+g+'</span>').join("")+'</div>';
    html += '<div class="row" style="color:var(--muted);font-size:12px">数据整理：'+d.updated+'</div>';
    html += '<div class="acts">'+
      (siteUrl?'<a class="btn alt" href="'+siteUrl+'" target="_blank" rel="noopener">访问官网</a>':"")+
      '<button class="btn ghost" onclick="copyInfo('+d.id+')">复制投稿信息</button>'+
      '</div>';
    m.innerHTML = html;
    $("#mask").classList.add("show");
  }
  function closeModal(){ $("#mask").classList.remove("show"); }
  $("#mask").onclick = e=>{ if(e.target.id==="mask") closeModal(); };
  document.addEventListener("keydown", e=>{ if(e.key==="Escape") closeModal(); });

  function copyInfo(id){
    const d = LIT_DATA.find(x=>x.id===id);
    let t = d.name + "\n类型：" + d.type + "｜地域：" + d.region + "｜主办：" + (d.publisher||d.organizer||d.wechat||"") +
      "\n征稿文体：" + (d.genres||[]).join("、") + "\n征稿要点：" + d.blurb + "\n投稿要求：" + d.requirement +
      "\n稿费：" + payLine(d);
    if(isEvent(d)) t += "\n截稿日期：" + d.deadline + "\n主题：" + d.theme + "\n投稿邮箱：" + d.contact;
    else if(d.type==="公众号") t += "\n平台：" + (d.platform||"微信") + "\n投稿方式：" + (d.email||d.wechat||"公众号后台");
    else t += "\n投稿邮箱：" + (d.email||"以官网为准") + "\n投稿地址：" + (d.address||"—");
    navigator.clipboard.writeText(t).then(()=>alert("已复制「"+d.name+"」投稿信息")).catch(()=>alert("复制失败，请手动选择"));
  }

  $("#q").addEventListener("input", e=>{ state.q=e.target.value; render(); });
  $("#sort").addEventListener("change", e=>{ state.sort=e.target.value; render(); });
  document.querySelectorAll("#tabs .tab").forEach(t=>{
    t.onclick = ()=>{ state.view=t.dataset.view; state.type=state.region=state.genre=state.status=state.anon=""; render(); };
  });
  render();

window.closeModal=closeModal; window.copyInfo=copyInfo;
